import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD与SIMT混合算子性能优化","link":"/guide/operator_practice/simd_simt_hybrid_optimization/simd_simt_hybrid_optimization"},{"text":"计算优化","link":"/guide/operator_practice/simd_simt_hybrid_optimization/compute_optimization/simt_branch_judgment"},{"text":"通过SIMT实现分支判断","link":"/guide/operator_practice/simd_simt_hybrid_optimization/compute_optimization/simt_branch_judgment"}]},"headers":[],"relativePath":"guide/operator_practice/simd_simt_hybrid_optimization/compute_optimization/simt_branch_judgment.md","filePath":"guide/operator_practice/simd_simt_hybrid_optimization/compute_optimization/simt_branch_judgment.md","lastUpdated":1787050286000}'),c={name:"guide/operator_practice/simd_simt_hybrid_optimization/compute_optimization/simt_branch_judgment.md"};function t(e,s,i,_,d,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>通过SIMT实现分支判断<span id="ZH-CN_TOPIC_0000002552896537"></span></h1><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 该性能优化建议适用于如下型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div></div><p>【优先级】高</p><p>【描述】基于SIMD编程模型实现的批量数据计算性能很高，但在算子实现逻辑中涉及分支判断时，基于SIMD的计算操作会变得相对复杂，导致性能下降。此时，可以考虑采用SIMT方式，因为SIMT编程更为灵活，更适合处理分支判断的场景。</p><p>【样例介绍】以floor_mod算子为例，算子功能为将输入x的每个元素除以输入y的对应元素，获取余数。该余数应与除数y具有相同的符号，且其绝对值应小于y的绝对值。在计算过程中，需要判断y中每个元素的符号以及余数与该元素绝对值的大小关系。完整的算子实现代码请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/05_simd_simt_hybrid/02_best_practices/simd_simt_high_performance">SIMT与SIMD混合编程高性能优化样例</a>。</p><p><strong>表1</strong> 样例规格</p><table><thead><tr><th>名称</th><th>name</th><th>shape</th><th>data type</th><th>format</th></tr></thead><tbody><tr><td rowspan="2">算子输入</td><td>x</td><td>[8192, 8192]</td><td>int32</td><td>ND</td></tr><tr><td>y</td><td>[8192, 8192]</td><td>int32</td><td>ND</td></tr><tr><td>算子输出</td><td>z</td><td>[8192, 8192]</td><td>int32</td><td>ND</td></tr></tbody></table><p>SIMT线程层次结构为：</p><ul><li>核函数（Kernel）启动核数：64</li><li>单次SIMT VF调用线程数：1024</li></ul><p>【反例】</p><p>基于SIMD Reg矢量计算的floor_mod算子实现：对应样例中的场景1（SCENARIO_NUM=1）。该场景使用 <code>asc_copy_gm2ub_align</code> 和 <code>asc_copy_ub2gm_align</code> 完成GM与Unified Buffer（UB）之间的数据搬运，在UB上使用SIMD VF函数实现计算。由于SIMD无法直接通过普通if else语句表达逐元素分支判断，因此需要使用多个矢量计算API完成符号比较、条件组合和结果选择，相关代码如下。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">floor_mod_simd</span><span class="p">(</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">z_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">x_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">y_addr</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_vf_len</span><span class="p">()</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">int32_t</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">loop_times</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ceil_div</span><span class="p">(</span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">x_value</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">y_value</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">mod_value</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">temp_value</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">default_value</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">sign_value</span><span class="p">;</span>

<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">select_mask</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">adjust_mask</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">mask_count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">count</span><span class="p">;</span>

<span class="w">    </span><span class="n">asc_duplicate_scalar</span><span class="p">(</span><span class="n">default_value</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="p">(</span><span class="mi">-1</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_duplicate_scalar</span><span class="p">(</span><span class="n">sign_value</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">FMOD_B32_SIGN</span><span class="p">));</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loop_times</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">mask_count</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">x_value</span><span class="p">,</span><span class="w"> </span><span class="n">x_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>

<span class="w">        </span><span class="n">asc_div</span><span class="p">(</span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">x_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_mul</span><span class="p">(</span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_sub</span><span class="p">(</span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">x_value</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>

<span class="w">        </span><span class="n">asc_ne_scalar</span><span class="p">(</span><span class="n">select_mask</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="p">(</span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_select</span><span class="p">(</span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">default_value</span><span class="p">,</span><span class="w"> </span><span class="n">select_mask</span><span class="p">);</span>

<span class="w">        </span><span class="n">asc_add</span><span class="p">(</span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_ne_scalar</span><span class="p">(</span><span class="n">adjust_mask</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="p">(</span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_and</span><span class="p">(</span><span class="n">x_value</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">sign_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_and</span><span class="p">(</span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">sign_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_ne</span><span class="p">(</span><span class="n">select_mask</span><span class="p">,</span><span class="w"> </span><span class="n">x_value</span><span class="p">,</span><span class="w"> </span><span class="n">y_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_and</span><span class="p">(</span><span class="n">adjust_mask</span><span class="p">,</span><span class="w"> </span><span class="n">select_mask</span><span class="p">,</span><span class="w"> </span><span class="n">adjust_mask</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_select</span><span class="p">(</span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">temp_value</span><span class="p">,</span><span class="w"> </span><span class="n">adjust_mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">z_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">mod_value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>【正例】</p><p>基于SIMT的floor_mod算子实现：对应样例中的场景3（SCENARIO_NUM=3）。该场景同样使用搬运接口完成GM与UB之间的数据搬运，在UB上采用SIMT编程方式实现计算过程，通过if else语句完成分支判断，代码如下所示。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">floor_mod_simt_contiguous</span><span class="p">(</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">y_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">index</span><span class="p">];</span>
<span class="w">        </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">rem</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="n">y_value</span><span class="p">;</span>
<span class="w">        </span><span class="kt">bool</span><span class="w"> </span><span class="n">signs_differ</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">rem</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="p">(</span><span class="n">y_value</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">0</span><span class="p">));</span>
<span class="w">        </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">signs_differ</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="p">(</span><span class="n">rem</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="mi">0</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">z</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">rem</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_value</span><span class="p">;</span>
<span class="w">        </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">z</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">rem</span><span class="p">;</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>【性能对比】</p><p>在核数相同、输入输出规格相同、均使用搬运接口完成GM与UB之间数据搬运的情况下，对比场景1和场景3的性能数据如下。</p><p>除Task Duration外，其余指标均为所有Thread Block上的平均值。</p><table><thead><tr><th align="left">场景</th><th align="left">实现方式</th><th align="center">核数</th><th align="right">Task Duration(μs)</th><th align="right">aiv_vec_time(μs)</th><th align="right">aiv_vec_ratio</th><th align="right">aiv_mte2_time(μs)</th><th align="right">aiv_mte2_ratio</th></tr></thead><tbody><tr><td align="left">场景1</td><td align="left">SIMD Reg矢量计算</td><td align="center">64</td><td align="right">525.736</td><td align="right">509.987</td><td align="right">0.989</td><td align="right">217.341</td><td align="right">0.421</td></tr><tr><td align="left">场景3</td><td align="left">SIMT连续访问UB</td><td align="center">64</td><td align="right">463.179</td><td align="right">301.474</td><td align="right">0.668</td><td align="right">437.055</td><td align="right">0.968</td></tr></tbody></table><p>相比场景1，场景3使用SIMT直接表达floor_mod中的分支判断逻辑，aiv_vec_time从509.987μs降低至301.474μs，下降约40.9%，说明Vector计算侧耗时明显降低。端到端Task Duration从525.736μs降低至463.179μs，下降约11.9%，场景3的aiv_mte2_ratio达到0.968，主要瓶颈已转为MTE2 Bound，即算子性能的最大影响转变为GM到UB的搬运效率。</p></article></div>`,1)])])}const m=a(c,[["render",t]]);export{r as __pageData,m as default};
